// ================= JSON PERSISTENCE HELPERS =================
function loadJsonSafe(filePath, fallback) {
    try {
        if (fs.existsSync(filePath)) {
            return JSON.parse(fs.readFileSync(filePath, "utf8"));
        }
    } catch (e) {}
    return fallback;
}

function saveJsonSafe(filePath, data) {
    try {
        fs.mkdirSync(path.dirname(filePath), { recursive: true });
        fs.writeFileSync(filePath, JSON.stringify(data, null, 2), "utf8");
    } catch (e) {
        console.warn("[Storage] Save warning:", e.message);
    }
}

// ================= ARABIC NORMALIZATION (v8 BULLETPROOF) =================
function normalizeArabic(text) {
    if (!text) return "";
    let s = String(text).normalize("NFKC").toLowerCase();
    const easternDigits = ["\u0660","\u0661","\u0662","\u0663","\u0664","\u0665","\u0666","\u0667","\u0668","\u0669"];
    for (let i = 0; i < 10; i++) {
        s = s.split(easternDigits[i]).join(String(i));
    }
    s = s.replace(/[\u064B-\u065F\u0670\u0640\u200B-\u200F\u202A-\u202E\u2066-\u2069\uFEFF]/g, "");
    s = s.replace(/[\u0622\u0623\u0625\u0671]/g, "\u0627");
    s = s.replace(/\u0629/g, "\u0647");
    s = s.replace(/\u0649/g, "\u064A");
    s = s.replace(/\u064A\u0621/g, "\u064A");
    s = s.replace(/\u0626/g, "\u064A");
    s = s.replace(/\u0624/g, "\u0648");
    s = s.replace(/\.pdf$/i, "");
    s = s.replace(/course[_\s-]*\d+/gi, " ");
    s = s.replace(/([\u0621-\u064Aa-z])([0-9])/gi, "$1 $2");
    s = s.replace(/([0-9])([\u0621-\u064Aa-z])/gi, "$1 $2");
    s = s.replace(/[^\u0621-\u064Aa-z0-9\s]/gi, " ");
    s = s.replace(/\s+/g, " ").trim();
    return s;
}

function stripAlPrefix(token) {
    if (!token) return "";
    if (token.length >= 5 && token.startsWith("\u0627\u0644")) return token.slice(2);
    if (token.length >= 6 && (token.startsWith("\u0648\u0627\u0644") || token.startsWith("\u0628\u0627\u0644"))) return token.slice(3);
    if (token.length >= 5 && token.startsWith("\u0644\u0644")) return token.slice(2);
    return token;
}

function isOneEditAway(a, b) {
    if (a === b) return true;
    const la = a.length, lb = b.length;
    if (Math.abs(la - lb) > 1) return false;
    let i = 0, j = 0, edits = 0;
    while (i < la && j < lb) {
        if (a[i] === b[j]) { i++; j++; }
        else {
            edits++;
            if (edits > 1) return false;
            if (la > lb) i++;
            else if (lb > la) j++;
            else { i++; j++; }
        }
    }
    if (i < la || j < lb) edits++;
    return edits <= 1;
}

function collapseRepeatedChars(text) {
    return text.replace(/(.)\1{2,}/g, "$1");
}

function parseCsvLine(line) {
    const out = [];
    let cur = "", inQuotes = false;
    for (let i = 0; i < line.length; i++) {
        const ch = line[i];
        if (inQuotes) {
            if (ch === '"' && line[i + 1] === '"') { cur += '"'; i++; }
            else if (ch === '"') { inQuotes = false; }
            else { cur += ch; }
        } else {
            if (ch === '"') { inQuotes = true; }
            else if (ch === ",") { out.push(cur.trim()); cur = ""; }
            else { cur += ch; }
        }
    }
    out.push(cur.trim());
    return out;
}

function extractInviteCode(urlOrCode) {
    if (!urlOrCode) return "";
    const match = String(urlOrCode).match(/chat\.whatsapp\.com\/([A-Za-z0-9]{15,30})/i);
    if (match) return match[1];
    if (/^[A-Za-z0-9]{15,30}$/.test(urlOrCode.trim())) return urlOrCode.trim();
    return "";
}

function baseUserId(jid) {
    return String(jid || "").split(":")[0].split("@")[0];
}

function hasAnyKeyword(normalizedText, keywordList) {
    const padded = ` ${normalizedText} `;
    for (const kw of keywordList) {
        const nk = normalizeArabic(kw);
        if (nk && (padded.includes(` ${nk} `) || normalizedText.includes(nk))) return true;
    }
    return false;
}

function matchTriggerPrefix(normRemainder, triggerList) {
    for (const trig of triggerList) {
        const nt = normalizeArabic(trig);
        if (!nt) continue;
        if (normRemainder === nt) return { matched: true, rest: "" };
        if (normRemainder.startsWith(nt + " ")) return { matched: true, rest: normRemainder.slice(nt.length).trim() };
    }
    return { matched: false, rest: normRemainder };
}

