// ================= PER-USER CHAT COOLDOWN & ANTI-SPAM FLOOD GUARD =================
class UserChatCooldown {
    constructor(cooldownMinutes) {
        this.cooldownMs = Math.max(0, cooldownMinutes) * 60 * 1000;
        this.lastChatMap = new Map();
    }
    isUserOnCooldown(userJid) {
        if (!userJid || this.cooldownMs <= 0) return false;
        const lastTs = this.lastChatMap.get(baseUserId(userJid)) || 0;
        return (Date.now() - lastTs) < this.cooldownMs;
    }
    remainingSeconds(userJid) {
        const lastTs = this.lastChatMap.get(baseUserId(userJid)) || 0;
        return Math.max(0, Math.ceil((this.cooldownMs - (Date.now() - lastTs)) / 1000));
    }
    markUserChatted(userJid) {
        if (!userJid) return;
        this.lastChatMap.set(baseUserId(userJid), Date.now());
    }
}

class FloodGuard {
    constructor(maxMsgs = 6, windowMs = 8000) {
        this.maxMsgs = maxMsgs;
        this.windowMs = windowMs;
        this.buckets = new Map();
        this.lastWarned = new Map();
    }
    checkFlood(userJid) {
        const uid = baseUserId(userJid);
        const now = Date.now();
        const arr = (this.buckets.get(uid) || []).filter(ts => (now - ts) < this.windowMs);
        arr.push(now);
        this.buckets.set(uid, arr);
        if (arr.length >= this.maxMsgs) {
            const lastW = this.lastWarned.get(uid) || 0;
            if ((now - lastW) > 30000) {
                this.lastWarned.set(uid, now);
                return true;
            }
        }
        return false;
    }
}

const userChatCooldown = new UserChatCooldown(CONFIG.chatCooldownMinutes);
const floodGuard = new FloodGuard(6, 8000);

// ================= MEMBER MEMORY, LEADERBOARD & MISSING TRACKER =================
class MemberStore {
    constructor(filePath) {
        this.filePath = filePath;
        this.data = loadJsonSafe(filePath, {});
    }
    touch(userJid, displayName) {
        const uid = baseUserId(userJid);
        if (!uid) return null;
        if (!this.data[uid]) {
            this.data[uid] = { name: displayName || uid, points: 0, major: "", quizzesTaken: 0, lastSeen: Date.now() };
        } else {
            if (displayName && displayName !== "Student") this.data[uid].name = displayName;
            this.data[uid].lastSeen = Date.now();
        }
        return this.data[uid];
    }
    detectMajor(userJid, rawText) {
        const uid = baseUserId(userJid);
        const rec = this.data[uid];
        if (!rec || rec.major) return;
        const norm = normalizeArabic(rawText);
        const majors = [
            ["cis", "CIS"], ["\u0627\u0646\u0638\u0645\u0629 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a", "CIS"],
            ["\u0627\u062f\u0627\u0631\u0629 \u0627\u0639\u0645\u0627\u0644", "\u0625\u062f\u0627\u0631\u0629 \u0623\u0639\u0645\u0627\u0644"],
            ["\u0645\u062d\u0627\u0633\u0628\u0629", "\u0645\u062d\u0627\u0633\u0628\u0629"],
            ["\u062a\u0631\u0628\u064a\u0629", "\u062a\u0631\u0628\u064a\u0629"],
            ["\u0642\u0627\u0646\u0648\u0646", "\u0642\u0627\u0646\u0648\u0646"],
            ["\u062a\u0633\u0648\u064a\u0642", "\u062a\u0633\u0648\u064a\u0642"]
        ];
        if (norm.includes("\u062a\u062e\u0635\u0635\u064a") || norm.includes("\u0627\u062f\u0631\u0633")) {
            for (const [kw, label] of majors) {
                if (norm.includes(normalizeArabic(kw))) {
                    rec.major = label;
                    this.save();
                    break;
                }
            }
        }
    }
    addPoints(userJid, displayName, pts) {
        const rec = this.touch(userJid, displayName);
        if (!rec) return 0;
        rec.points = (rec.points || 0) + pts;
        this.save();
        return rec.points;
    }
    getTop(limit = 5) {
        return Object.entries(this.data)
            .filter(([, v]) => (v.points || 0) > 0)
            .sort((a, b) => (b[1].points || 0) - (a[1].points || 0))
            .slice(0, limit);
    }
    getProfileHint(userJid) {
        const rec = this.data[baseUserId(userJid)];
        if (!rec) return "";
        const bits = [];
        if (rec.major) bits.push(`Major: ${rec.major}`);
        if (rec.points > 0) bits.push(`QuizPoints: ${rec.points}`);
        return bits.join(", ");
    }
    save() { saveJsonSafe(this.filePath, this.data); }
}

class MissingTracker {
    constructor(filePath) {
        this.filePath = filePath;
        this.data = loadJsonSafe(filePath, {});
    }
    record(queryLabel, requesterName) {
        if (!queryLabel || queryLabel.length < 3) return;
        const key = normalizeArabic(queryLabel);
        if (!this.data[key]) {
            this.data[key] = { label: queryLabel, count: 0, lastBy: requesterName, updatedAt: new Date().toISOString() };
        }
        this.data[key].count += 1;
        this.data[key].lastBy = requesterName;
        this.data[key].updatedAt = new Date().toISOString();
        saveJsonSafe(this.filePath, this.data);
    }
    listTop(limit = 15) {
        return Object.values(this.data)
            .sort((a, b) => b.count - a.count)
            .slice(0, limit);
    }
}

const memberStore = new MemberStore(PATHS.members);
const missingTracker = new MissingTracker(PATHS.missing);

// ================= 3-STRIKE MODERATION & ANTI-LINK MANAGER =================
class ModerationManager {
    constructor(filePath) {
        this.filePath = filePath;
        this.warnings = loadJsonSafe(filePath, {});
        this.normalizedBadPhrases = Array.from(
            new Set(AR.profanityWords.map(w => collapseRepeatedChars(normalizeArabic(w))).filter(Boolean))
        );
        this.allowedInviteCode = extractInviteCode(CONFIG.targetGroupInviteUrl);
    }
    containsProfanity(rawText) {
        if (!rawText) return false;
        const norm = collapseRepeatedChars(normalizeArabic(rawText));
        if (!norm) return false;
        const padded = ` ${norm} `;
        for (const bad of this.normalizedBadPhrases) {
            if (padded.includes(` ${bad} `)) return true;
        }
        return false;
    }
    containsUnauthorizedLink(rawText) {
        if (!rawText) return false;
        const text = String(rawText);
        // Check WhatsApp group invite links (allow own group link)
        const waMatch = text.match(/chat\.whatsapp\.com\/([A-Za-z0-9]{15,30})/i);
        if (waMatch) {
            if (this.allowedInviteCode && waMatch[1] === this.allowedInviteCode) return false;
            return true;
        }
        // Block external Telegram/Discord/shortener spam links
        if (/(t\.me\/|telegram\.me\/|discord\.gg\/|bit\.ly\/|tinyurl\.com\/)/i.test(text)) {
            return true;
        }
        return false;
    }
    addStrike(groupJid, userJid) {
        const key = `${groupJid}::${baseUserId(userJid)}`;
        const current = (this.warnings[key] || 0) + 1;
        this.warnings[key] = current;
        saveJsonSafe(this.filePath, this.warnings);
        return current;
    }
    resetStrikes(groupJid, userJid) {
        const key = `${groupJid}::${baseUserId(userJid)}`;
        delete this.warnings[key];
        saveJsonSafe(this.filePath, this.warnings);
    }
}

const moderation = new ModerationManager(PATHS.warnings);


// ================= DIRECT GOOGLE DRIVE CLOUD STREAMING (FOR RENDER / KOYEB) =================
const zlib = require("zlib");

function isCloudDriveMode() {
    return !fs.existsSync(CONFIG.uniquePdfsDir) && Boolean(CONFIG.driveFolderId);
}

async function fetchDriveIndexCsvCloud() {
    if (!CONFIG.driveIndexCsvId) return "";
    const urls = [];
    if (CONFIG.driveApiKey) {
        urls.push(`https://www.googleapis.com/drive/v3/files/${CONFIG.driveIndexCsvId}?alt=media&key=${encodeURIComponent(CONFIG.driveApiKey)}`);
    }
    urls.push(`https://drive.google.com/uc?export=download&id=${CONFIG.driveIndexCsvId}`);
    for (const url of urls) {
        try {
            const resp = await fetch(url, { redirect: "follow" });
            if (resp.ok) {
                const txt = await resp.text();
                if (txt && txt.includes("stored_filename")) return txt;
            }
        } catch (e) {}
    }
    return "";
}

async function listDriveFolderCloud() {
    if (!CONFIG.driveApiKey || !CONFIG.driveFolderId) return [];
    const files = [];
    let pageToken = "";
    try {
        do {
            const q = encodeURIComponent(`'${CONFIG.driveFolderId}' in parents and trashed = false`);
            const fields = encodeURIComponent("nextPageToken,files(id,name,size)");
            const url = `https://www.googleapis.com/drive/v3/files?q=${q}&fields=${fields}&pageSize=1000&key=${encodeURIComponent(CONFIG.driveApiKey)}${pageToken ? `&pageToken=${encodeURIComponent(pageToken)}` : ""}`;
            const resp = await fetch(url);
            if (!resp.ok) {
                console.warn(`[CloudDrive] Folder list HTTP ${resp.status}`);
                break;
            }
            const data = await resp.json();
            for (const f of (data.files || [])) {
                if (f.name && f.name.toLowerCase().endsWith(".pdf")) {
                    files.push({ id: f.id, name: f.name, sizeBytes: parseInt(f.size || "0", 10) || 0 });
                }
            }
            pageToken = data.nextPageToken || "";
        } while (pageToken && files.length < 10000);
    } catch (err) {
        console.warn("[CloudDrive] List error:", err.message);
    }
    return files;
}

async function downloadDrivePdfToTemp(driveFileId, filename) {
    const tmpDir = "/tmp/sheikh_pdf_cache";
    fs.mkdirSync(tmpDir, { recursive: true });
    const safeName = filename.replace(/[\\/]/g, "_");
    const tmpPath = path.join(tmpDir, `${Date.now()}_${safeName}`);
    const urls = [];
    if (CONFIG.driveApiKey) {
        urls.push(`https://www.googleapis.com/drive/v3/files/${driveFileId}?alt=media&key=${encodeURIComponent(CONFIG.driveApiKey)}`);
    }
    urls.push(`https://drive.google.com/uc?export=download&confirm=t&id=${driveFileId}`);
    for (const url of urls) {
        try {
            const resp = await fetch(url, { redirect: "follow" });
            if (!resp.ok) continue;
            const ctype = (resp.headers.get("content-type") || "").toLowerCase();
            if (ctype.includes("text/html")) continue;
            const arrBuf = await resp.arrayBuffer();
            const buf = Buffer.from(arrBuf);
            if (buf.length > 512) {
                fs.writeFileSync(tmpPath, buf);
                return tmpPath;
            }
        } catch (e) {}
    }
    return null;
}

function restoreAuthFromEnvIfNeeded() {
    if (!CONFIG.whatsappAuthB64) return;
    const credsPath = path.join(CONFIG.authDir, "creds.json");
    if (fs.existsSync(credsPath)) return;
    try {
        fs.mkdirSync(CONFIG.authDir, { recursive: true });
        const raw = zlib.gunzipSync(Buffer.from(CONFIG.whatsappAuthB64, "base64")).toString("utf8");
        const bundle = JSON.parse(raw);
        for (const [fname, content] of Object.entries(bundle)) {
            fs.writeFileSync(path.join(CONFIG.authDir, fname), content, "utf8");
        }
        console.log(`[Auth] Restored ${Object.keys(bundle).length} session files from WHATSAPP_AUTH_B64.`);
    } catch (err) {
        console.warn("[Auth] Failed to restore WHATSAPP_AUTH_B64:", err.message);
    }
}

function printAuthExportHintOnce() {
    if (CONFIG.whatsappAuthB64 || fs.existsSync("/content/drive/MyDrive")) return;
    try {
        const credsPath = path.join(CONFIG.authDir, "creds.json");
        if (!fs.existsSync(credsPath)) return;
        const bundle = { "creds.json": fs.readFileSync(credsPath, "utf8") };
        const b64 = zlib.gzipSync(Buffer.from(JSON.stringify(bundle), "utf8")).toString("base64");
        console.log("\n=== COPY FULL WHATSAPP_AUTH_B64 TO RENDER ENV ===");
        console.log(b64);
        console.log("=================================================\n");
    } catch (e) {}
}

// ================= BULLETPROOF VAULT SEARCH ENGINE =================
class SheikhVaultIndex {
    constructor() {
        this.items = [];
        this.lastReloadTime = 0;
        this.totalSizeMb = 0;
    }
    buildItem(fname, caption, fullPath, sizeBytes, driveFileId = null) {
        const sizeMb = +(sizeBytes / (1024 * 1024)).toFixed(2);
        const combinedSearchText = normalizeArabic(`${fname} ${caption}`);
        const tokens = combinedSearchText.split(" ").filter(t => t.length > 1 || /^\d+$/.test(t));
        const strippedTokens = Array.from(new Set(tokens.map(stripAlPrefix).filter(Boolean)));
        return {
            storedFilename: fname,
            caption,
            fullPath,
            driveFileId,
            sizeBytes,
            sizeMb,
            sizeKb: +(sizeBytes / 1024).toFixed(1),
            normalizedText: combinedSearchText,
            tokens,
            strippedTokens,
            tags: {
                isBook: hasAnyKeyword(combinedSearchText, AR.filterBook),
                isMidterm: hasAnyKeyword(combinedSearchText, AR.filterMidterm),
                isFinal: hasAnyKeyword(combinedSearchText, AR.filterFinal),
                isExam: hasAnyKeyword(combinedSearchText, AR.filterExams),
                isSummary: hasAnyKeyword(combinedSearchText, AR.filterSummary)
            }
        };
    }
    reloadIfNeeded(force = false) {
        const now = Date.now();
        if (!force && now - this.lastReloadTime < 45000 && this.items.length > 0) return;
        this.lastReloadTime = now;

        const csvEntries = new Map();
        if (fs.existsSync(CONFIG.indexCsvPath)) {
            try {
                const lines = fs.readFileSync(CONFIG.indexCsvPath, "utf8").split(/\r?\n/);
                for (let i = 1; i < lines.length; i++) {
                    const line = lines[i].trim();
                    if (!line) continue;
                    const parts = parseCsvLine(line);
                    if (parts.length >= 4) {
                        csvEntries.set(parts[1].trim(), { caption: parts[0].trim(), sizeKb: parseFloat(parts[3]) || 0 });
                    }
                }
            } catch (err) {
                console.warn("[Vault] CSV read warning:", err.message);
            }
        }

        const loadedItems = [];
        let totalBytes = 0;
        if (fs.existsSync(CONFIG.uniquePdfsDir)) {
            const files = fs.readdirSync(CONFIG.uniquePdfsDir);
            for (const fname of files) {
                if (!fname.toLowerCase().endsWith(".pdf")) continue;
                const fullPath = path.join(CONFIG.uniquePdfsDir, fname);
                try {
                    const stat = fs.statSync(fullPath);
                    if (!stat.isFile()) continue;
                    totalBytes += stat.size;
                    const csvMeta = csvEntries.get(fname);
                    const caption = (csvMeta && csvMeta.caption) ? csvMeta.caption : fname;
                    loadedItems.push(this.buildItem(fname, caption, fullPath, stat.size));
                } catch (e) {}
            }
        } else if (csvEntries.size > 0) {
            for (const [fname, meta] of csvEntries.entries()) {
                const sizeBytes = Math.round(meta.sizeKb * 1024);
                totalBytes += sizeBytes;
                loadedItems.push(this.buildItem(fname, meta.caption, path.join(CONFIG.uniquePdfsDir, fname), sizeBytes));
            }
        }

        if (loadedItems.length > 0) {
            this.items = loadedItems;
            this.totalSizeMb = +(totalBytes / (1024 * 1024)).toFixed(2);
            console.log(`[Vault] Indexed ${this.items.length} unique PDFs (${this.totalSizeMb} MB) from local disk.`);
        }
    }
    async reloadCloudIfNeeded(force = false) {
        if (!isCloudDriveMode()) {
            this.reloadIfNeeded(force);
            return;
        }
        const now = Date.now();
        if (!force && now - this.lastReloadTime < 300000 && this.items.length > 0) return;
        this.lastReloadTime = now;
        console.log("[CloudDrive] Syncing Bank Al-Ma'rifa index directly from Google Drive...");
        const csvText = await fetchDriveIndexCsvCloud();
        const csvEntries = new Map();
        if (csvText) {
            const lines = csvText.split(/\r?\n/);
            for (let i = 1; i < lines.length; i++) {
                const line = lines[i].trim();
                if (!line) continue;
                const parts = parseCsvLine(line);
                if (parts.length >= 4) {
                    csvEntries.set(parts[1].trim(), { caption: parts[0].trim(), sizeKb: parseFloat(parts[3]) || 0 });
                }
            }
        }
        const driveFiles = await listDriveFolderCloud();
        const loadedItems = [];
        let totalBytes = 0;
        for (const f of driveFiles) {
            totalBytes += f.sizeBytes;
            const csvMeta = csvEntries.get(f.name);
            const caption = (csvMeta && csvMeta.caption) ? csvMeta.caption : f.name;
            loadedItems.push(this.buildItem(f.name, caption, "", f.sizeBytes, f.id));
        }
        this.items = loadedItems;
        this.totalSizeMb = +(totalBytes / (1024 * 1024)).toFixed(2);
        console.log(`[CloudDrive] Ready! Indexed ${this.items.length} unique PDFs (${this.totalSizeMb} MB) directly from Google Drive.`);
    }
    search(rawQuery) {
        this.reloadIfNeeded(false);
        const normFull = normalizeArabic(rawQuery);
        const wantMidterm = hasAnyKeyword(normFull, AR.filterMidterm);
        const wantFinal = hasAnyKeyword(normFull, AR.filterFinal);
        const wantSummary = hasAnyKeyword(normFull, AR.filterSummary);
        const wantExams = hasAnyKeyword(normFull, AR.filterExams);
        const wantBook = hasAnyKeyword(normFull, AR.filterBook);

        const filterWordsSet = new Set([
            ...AR.filterMidterm.map(normalizeArabic),
            ...AR.filterFinal.map(normalizeArabic),
            ...AR.filterSummary.map(normalizeArabic),
            ...AR.filterExams.map(normalizeArabic),
            ...AR.filterBook.map(normalizeArabic)
        ]);
        const normalizedStopWords = new Set(Array.from(AR.stopWords).map(normalizeArabic));
        const allTokens = normFull.split(" ").filter(Boolean);
        const coreCourseTokens = allTokens.filter(
            t => !normalizedStopWords.has(t) && !filterWordsSet.has(t) && (t.length > 1 || /^\d+$/.test(t))
        );

        if (coreCourseTokens.length === 0) return { queryLabel: "", matches: [] };

        const corePhrase = coreCourseTokens.join(" ");
        const courseMatches = [];

        for (const item of this.items) {
            if (CONFIG.maxSendFileSizeMb > 0 && item.sizeMb > CONFIG.maxSendFileSizeMb) continue;
            let matchedTokens = 0, score = 0;
            for (const qToken of coreCourseTokens) {
                const qStem = stripAlPrefix(qToken);
                if (item.tokens.includes(qToken)) { matchedTokens += 1; score += 35; }
                else if (qStem.length >= 3 && item.strippedTokens.includes(qStem)) { matchedTokens += 1; score += 30; }
                else if (qStem.length >= 3 && item.normalizedText.includes(qStem)) { matchedTokens += 1; score += 22; }
                else if (qStem.length >= 5 && item.strippedTokens.some(t => t.length >= 5 && isOneEditAway(qStem, t))) { matchedTokens += 1; score += 18; }
            }
            const minRequired = coreCourseTokens.length <= 2 ? coreCourseTokens.length : Math.ceil(coreCourseTokens.length * 0.75);
            if (matchedTokens < minRequired) continue;
            if (item.normalizedText.includes(corePhrase)) score += 50;
            courseMatches.push({ item, score });
        }

        if (courseMatches.length === 0) return { queryLabel: corePhrase, matches: [] };

        let filtered = courseMatches;
        if (wantBook && !wantSummary && !wantExams) {
            const booksOnly = filtered.filter(x => x.item.tags.isBook);
            if (booksOnly.length > 0) filtered = booksOnly;
        } else if (!wantBook && (wantSummary || wantExams || wantMidterm || wantFinal)) {
            const nonBooks = filtered.filter(x => !x.item.tags.isBook);
            if (nonBooks.length > 0) filtered = nonBooks;
        }

        if (wantMidterm && !wantFinal) {
            const noFinalOnly = filtered.filter(x => !(x.item.tags.isFinal && !x.item.tags.isMidterm));
            if (noFinalOnly.length > 0) filtered = noFinalOnly;
            const midtermExact = filtered.filter(x => x.item.tags.isMidterm);
            if (midtermExact.length > 0) filtered = midtermExact;
        } else if (wantFinal && !wantMidterm) {
            const noMidtermOnly = filtered.filter(x => !(x.item.tags.isMidterm && !x.item.tags.isFinal));
            if (noMidtermOnly.length > 0) filtered = noMidtermOnly;
            const finalExact = filtered.filter(x => x.item.tags.isFinal);
            if (finalExact.length > 0) filtered = finalExact;
        }

        if (wantSummary && !wantExams) {
            const summariesExact = filtered.filter(x => x.item.tags.isSummary && !x.item.tags.isBook);
            if (summariesExact.length > 0) filtered = summariesExact;
            else {
                const nonExamFiles = filtered.filter(x => !x.item.tags.isExam);
                if (nonExamFiles.length > 0) filtered = nonExamFiles;
            }
        } else if (wantExams && !wantSummary) {
            const examsExact = filtered.filter(x => x.item.tags.isExam);
            if (examsExact.length > 0) filtered = examsExact;
        }

        for (const entry of filtered) {
            const t = entry.item.tags;
            if (wantMidterm && t.isMidterm) entry.score += 30;
            if (wantFinal && t.isFinal) entry.score += 30;
            if (wantSummary && t.isSummary) entry.score += 25;
            if (wantExams && t.isExam) entry.score += 25;
            if (wantBook && t.isBook) entry.score += 30;
            if (!wantBook && entry.item.sizeMb <= 15) entry.score += 5;
        }

        filtered.sort((a, b) => b.score - a.score);
        let displayLabel = corePhrase;
        if (wantSummary && wantMidterm) displayLabel = `${AR.filterSummary[0]} ${AR.filterMidterm[0]} ${corePhrase}`;
        else if (wantSummary && wantFinal) displayLabel = `${AR.filterSummary[0]} ${AR.filterFinal[0]} ${corePhrase}`;
        else if (wantExams && wantMidterm) displayLabel = `${AR.filterExams[0]} ${AR.filterMidterm[0]} ${corePhrase}`;
        else if (wantExams && wantFinal) displayLabel = `${AR.filterExams[0]} ${AR.filterFinal[0]} ${corePhrase}`;
        else if (wantMidterm) displayLabel = `${AR.filterMidterm[0]} ${corePhrase}`;
        else if (wantFinal) displayLabel = `${AR.filterFinal[0]} ${corePhrase}`;
        else if (wantBook) displayLabel = `${AR.filterBook[0]} ${corePhrase}`;

        return { queryLabel: displayLabel, matches: filtered.map(s => s.item) };
    }
}

// ================= PDF TEXT EXTRACTION (pdftotext / pdf-parse fallback) =================
async function extractPdfTextSnippet(pdfPath, maxChars = 4500) {
    if (!pdfPath || !fs.existsSync(pdfPath)) return "";
    // Fast native pdftotext (poppler-utils) if installed
    try {
        const out = execFileSync("pdftotext", ["-f", "1", "-l", "6", pdfPath, "-"], {
            encoding: "utf8",
            timeout: 8000,
            maxBuffer: 2 * 1024 * 1024
        });
        if (out && out.trim().length > 80) return out.trim().slice(0, maxChars);
    } catch (e) {}
    // Fallback to optional pdf-parse npm package if available
    try {
        const pdfParse = require("pdf-parse");
        const buf = fs.readFileSync(pdfPath);
        const parsed = await pdfParse(buf, { max: 6 });
        if (parsed && parsed.text && parsed.text.trim().length > 80) {
            return parsed.text.trim().slice(0, maxChars);
        }
    } catch (e) {}
    return "";
}

