async function callGeminiRaw(systemInstruction, userParts, { temperature = 0.7, maxOutputTokens = 650, jsonMode = false } = {}) {
    if (!CONFIG.geminiApiKey) return null;
    const isAqKey = CONFIG.geminiApiKey.startsWith("AQ.");
    const modelsToTry = Array.from(new Set([CONFIG.geminiModel, "gemini-2.5-flash", "gemini-2.5-flash-lite", "gemini-2.0-flash"]));

    for (const modelName of modelsToTry) {
        try {
            const url = isAqKey
                ? `https://aiplatform.googleapis.com/v1/publishers/google/models/${modelName}:generateContent?key=${encodeURIComponent(CONFIG.geminiApiKey)}`
                : `https://generativelanguage.googleapis.com/v1beta/models/${modelName}:generateContent?key=${encodeURIComponent(CONFIG.geminiApiKey)}`;
            const genConfig = { temperature, maxOutputTokens, thinkingConfig: { thinkingBudget: 0 } };
            if (jsonMode) genConfig.responseMimeType = "application/json";

            const resp = await fetch(url, {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    "x-goog-api-key": CONFIG.geminiApiKey
                },
                body: JSON.stringify({
                    system_instruction: { parts: [{ text: systemInstruction }] },
                    contents: [{ role: "user", parts: userParts }],
                    generationConfig: genConfig
                })
            });
            if (!resp.ok) {
                const errBody = await resp.text();
                console.warn(`[Gemini] ${modelName} HTTP ${resp.status}: ${errBody.slice(0, 140)}`);
                continue;
            }
            const data = await resp.json();
            const parts = data?.candidates?.[0]?.content?.parts || [];
            const visibleParts = parts.filter(p => !p.thought && typeof p.text === "string").map(p => p.text.trim()).filter(Boolean);
            const replyText = visibleParts.join("\n").trim();
            if (replyText) return replyText;
        } catch (err) {
            console.warn(`[Gemini] Error on ${modelName}:`, err.message);
        }
    }
    return null;
}

