function normalizeChoiceLetter(raw) {
    const s = normalizeArabic(raw).trim();
    if (s === "\u0627" || s === "a" || s === "1") return "\u0627";
    if (s === "\u0628" || s === "b" || s === "2") return "\u0628";
    if (s === "\u062c" || s === "c" || s === "3") return "\u062c";
    if (s === "\u062f" || s === "d" || s === "4") return "\u062f";
    return "";
}

