// ================= COMMAND PARSER (ADMIN + STUDY + VAULT) =================
function parseSheikhCommand(rawText, requireWakeWord) {
    if (!rawText) return null;
    const trimmed = rawText.trim();
    const norm = normalizeArabic(trimmed);

    let triggered = false;
    let remainder = norm;

    for (const wake of AR.wakeWords) {
        const normWake = normalizeArabic(wake);
        if (norm === normWake || norm.startsWith(normWake + " ")) {
            triggered = true;
            remainder = norm.slice(normWake.length).trim();
            break;
        }
    }

    if (!triggered) {
        if (!requireWakeWord) {
            remainder = norm;
        } else {
            return null;
        }
    }

    if (!remainder || AR.helpCommands.some(cmd => remainder === normalizeArabic(cmd))) {
        return { type: "HELP", rawRemainder: remainder };
    }
    if (AR.statsCommands.some(cmd => remainder.includes(normalizeArabic(cmd)))) {
        return { type: "STATS", rawRemainder: remainder };
    }

    // Admin commands
    if (matchTriggerPrefix(remainder, AR.adminLockTriggers).matched) return { type: "ADMIN_LOCK" };
    if (matchTriggerPrefix(remainder, AR.adminUnlockTriggers).matched) return { type: "ADMIN_UNLOCK" };
    if (matchTriggerPrefix(remainder, AR.adminKickTriggers).matched) return { type: "ADMIN_KICK" };
    if (matchTriggerPrefix(remainder, AR.adminDeleteTriggers).matched) return { type: "ADMIN_DELETE" };
    if (matchTriggerPrefix(remainder, AR.adminWarnTriggers).matched) return { type: "ADMIN_WARN" };
    if (AR.pardonCommands.some(cmd => remainder.includes(normalizeArabic(cmd)))) return { type: "ADMIN_PARDON" };
    if (matchTriggerPrefix(remainder, AR.adminLinksOff).matched) return { type: "ADMIN_LINKS_OFF" };
    if (matchTriggerPrefix(remainder, AR.adminLinksOn).matched) return { type: "ADMIN_LINKS_ON" };
    if (matchTriggerPrefix(remainder, AR.adminChatOff).matched) return { type: "ADMIN_CHAT_OFF" };
    if (matchTriggerPrefix(remainder, AR.adminChatOn).matched) return { type: "ADMIN_CHAT_ON" };

    const tagAll = matchTriggerPrefix(remainder, AR.adminTagAllTriggers);
    if (tagAll.matched) return { type: "ADMIN_TAG_ALL", message: tagAll.rest || trimmed };

    if (AR.missingListTriggers.some(cmd => remainder.includes(normalizeArabic(cmd)))) return { type: "ADMIN_MISSING_LIST" };
    if (AR.dailyChallengeTriggers.some(cmd => remainder.includes(normalizeArabic(cmd)))) return { type: "DAILY_CHALLENGE" };
    if (AR.leaderboardTriggers.some(cmd => remainder.includes(normalizeArabic(cmd)))) return { type: "LEADERBOARD" };
    if (AR.catchupTriggers.some(cmd => remainder.includes(normalizeArabic(cmd)))) return { type: "CATCHUP" };

    const quizMatch = matchTriggerPrefix(remainder, AR.quizTriggers);
    if (quizMatch.matched) return { type: "QUIZ", course: quizMatch.rest };

    const sumMatch = matchTriggerPrefix(remainder, AR.summarizeTriggers);
    if (sumMatch.matched) return { type: "SUMMARIZE", course: sumMatch.rest };

    return { type: "SEARCH", query: remainder, rawText: trimmed };
}

