const groupMetaCache = new Map();
async function getGroupMetadataSafe(sock, groupJid) {
    const cached = groupMetaCache.get(groupJid);
    if (cached && (Date.now() - cached.ts) < 300000) return cached.meta;
    try {
        const meta = await sock.groupMetadata(groupJid);
        groupMetaCache.set(groupJid, { meta, ts: Date.now() });
        return meta;
    } catch (e) { return null; }
}

async function isGroupAdmin(sock, groupJid, participantJid, fromMe = false) {
    if (fromMe) return true;
    const uid = baseUserId(participantJid);
    if (CONFIG.ownerNumbers.includes(uid)) return true;
    if (!groupJid || !groupJid.endsWith("@g.us")) return false;
    const meta = await getGroupMetadataSafe(sock, groupJid);
    if (!meta || !meta.participants) return false;
    const found = meta.participants.find(p => baseUserId(p.id) === uid);
    return Boolean(found && (found.admin === "admin" || found.admin === "superadmin"));
}

function extractMessageText(msg) {
    const m = msg.message;
    if (!m) return "";
    if (m.conversation) return m.conversation;
    if (m.extendedTextMessage && m.extendedTextMessage.text) return m.extendedTextMessage.text;
    if (m.imageMessage && m.imageMessage.caption) return m.imageMessage.caption;
    if (m.documentMessage && m.documentMessage.caption) return m.documentMessage.caption;
    if (m.videoMessage && m.videoMessage.caption) return m.videoMessage.caption;
    return "";
}

function isReplyToBot(msg, sock) {
    const ctx = msg?.message?.extendedTextMessage?.contextInfo;
    if (!ctx || !ctx.participant) return false;
    const botBase = baseUserId(sock.user?.id || "");
    return Boolean(botBase && baseUserId(ctx.participant) === botBase);
}

function getTargetParticipantFromMsg(msg) {
    const ctx = msg?.message?.extendedTextMessage?.contextInfo;
    if (ctx && ctx.participant) return ctx.participant;
    if (ctx && Array.isArray(ctx.mentionedJid) && ctx.mentionedJid.length > 0) return ctx.mentionedJid[0];
    return null;
}

async function deliverPdfMatches(sock, remoteJid, quotedMsg, searchResult, introOverride = null) {
    const toSend = searchResult.matches.slice(0, CONFIG.maxFilesPerReply);
    const remaining = searchResult.matches.slice(CONFIG.maxFilesPerReply, CONFIG.maxFilesPerReply + 5);
    const cacheKey = `${remoteJid}::${searchResult.queryLabel}`;
    const lastSent = recentSentCache.get(cacheKey) || 0;
    if (Date.now() - lastSent < CONFIG.pdfCooldownSeconds * 1000) return false;
    recentSentCache.set(cacheKey, Date.now());

    let introText = introOverride || `${AR.msgFoundPrefix}(${toSend.length})${AR.msgFoundMid}${searchResult.queryLabel}${AR.msgFoundSuffix}`;
    if (remaining.length > 0) {
        introText += AR.msgMoreFilesHeader + remaining.map((r, i) => `${i + 1}. ${r.storedFilename} (${r.sizeMb} MB)`).join("\n");
    }
    await sendBotMessage(sock, remoteJid, { text: introText }, { quoted: quotedMsg });

    for (const item of toSend) {
        let tempCloudPath = null;
        try {
            let sendPath = item.fullPath;
            if ((!sendPath || !fs.existsSync(sendPath)) && item.driveFileId) {
                tempCloudPath = await downloadDrivePdfToTemp(item.driveFileId, item.storedFilename);
                sendPath = tempCloudPath;
            }
            if (!sendPath || !fs.existsSync(sendPath)) continue;
            await sendBotMessage(
                sock,
                remoteJid,
                {
                    document: { url: sendPath },
                    mimetype: "application/pdf",
                    fileName: item.storedFilename,
                    caption: `${item.caption} (${item.sizeMb} MB)`
                },
                { quoted: quotedMsg }
            );
            runtimeStatus.filesSent += 1;
            await sleepMs(450);
        } catch (err) {
            console.error(`[PDF Send Error] ${item.storedFilename}:`, err.message);
        } finally {
            if (tempCloudPath && fs.existsSync(tempCloudPath)) {
                try { fs.unlinkSync(tempCloudPath); } catch (e) {}
            }
        }
    }
    return true;
}

async function applyModerationStrike(sock, remoteJid, msg, senderJid, reasonText) {
    const strikes = moderation.addStrike(remoteJid, senderJid);
    const userNum = baseUserId(senderJid);
    runtimeStatus.moderationActions += 1;
    console.log(`[Moderation] ${userNum} -> Strike ${strikes}/3 (${reasonText})`);
    try { await sock.sendMessage(remoteJid, { delete: msg.key }); } catch (e) {}

    if (strikes === 1) {
        await sendBotMessage(sock, remoteJid, {
            text: AR.msgWarn1.replace("{USER}", userNum).replace("{REASON}", reasonText),
            mentions: [senderJid]
        });
    } else if (strikes === 2) {
        await sendBotMessage(sock, remoteJid, {
            text: AR.msgWarn2.replace("{USER}", userNum).replace("{REASON}", reasonText),
            mentions: [senderJid]
        });
    } else {
        await sendBotMessage(sock, remoteJid, {
            text: AR.msgWarn3Kick.replace("{USER}", userNum),
            mentions: [senderJid]
        });
        await sleepMs(1400);
        try {
            await sock.groupParticipantsUpdate(remoteJid, [senderJid], "remove");
            moderation.resetStrikes(remoteJid, senderJid);
        } catch (kickErr) {
            console.error("[Moderation] Kick failed:", kickErr.message);
        }
    }
}

let loggedOutRetries = 0;

function checkAndResetIfPhoneChanged() {
    const credsFile = path.join(CONFIG.authDir, "creds.json");
    if (!CONFIG.pairingPhoneNumber || !fs.existsSync(credsFile)) return;
    try {
        const credsData = JSON.parse(fs.readFileSync(credsFile, "utf8"));
        const savedId = (credsData?.me?.id || "").split(":")[0].split("@")[0].replace(/[^0-9]/g, "");
        if (savedId && savedId !== CONFIG.pairingPhoneNumber) {
            console.log(`[Auth] Phone switched (${savedId} -> ${CONFIG.pairingPhoneNumber}). Resetting session...`);
            fs.rmSync(CONFIG.authDir, { recursive: true, force: true });
        }
    } catch (e) {}
}

// ================= MAIN WHATSAPP CONNECTION LOOP =================
async function startSheikhBot() {
    const baileys = await import("@whiskeysockets/baileys");
    const makeWASocket = baileys.default?.default || baileys.default || baileys.makeWASocket;
    const { useMultiFileAuthState, DisconnectReason, fetchLatestBaileysVersion, downloadMediaMessage } = baileys;
    const pino = (await import("pino")).default;

    restoreAuthFromEnvIfNeeded();
    checkAndResetIfPhoneChanged();
    fs.mkdirSync(CONFIG.authDir, { recursive: true });
    await vault.reloadCloudIfNeeded(true);
    loadCachedAllowedGroup();

    const { state, saveCreds } = await useMultiFileAuthState(CONFIG.authDir);
    const { version, isLatest } = await fetchLatestBaileysVersion();
    console.log(`[Baileys] WA Web v${version.join(".")} (isLatest: ${isLatest})`);

    const sock = makeWASocket({
        version,
        auth: state,
        logger: pino({ level: "silent" }),
        browser: ["Ubuntu", "Chrome", "20.0.04"],
        printQRInTerminal: false,
        syncFullHistory: false,
        markOnlineOnConnect: true,
        connectTimeoutMs: 60000,
        defaultQueryTimeoutMs: 60000,
        keepAliveIntervalMs: 25000
    });

    sock.ev.on("creds.update", saveCreds);

    if (!sock.authState.creds.registered) {
        if (!CONFIG.pairingPhoneNumber) {
            console.error("[Auth Error] Set PAIRING_PHONE_NUMBER (e.g. 97059xxxxxxx) to generate an 8-digit pairing code.");
            return;
        }
        setTimeout(async () => {
            try {
                const rawCode = await sock.requestPairingCode(CONFIG.pairingPhoneNumber);
                const formatted = rawCode?.match(/.{1,4}/g)?.join("-") || rawCode;
                runtimeStatus.pairingCode = formatted;
                console.log("\n======================================================");
                console.log(`WHATSAPP 8-DIGIT PAIRING CODE:  ${formatted}`);
                console.log("WhatsApp -> Linked Devices -> Link with phone number");
                console.log("======================================================\n");
            } catch (err) {
                console.error("[Auth] Failed pairing code:", err.message);
            }
        }, 4500);
    }

    sock.ev.on("connection.update", async (update) => {
        const { connection, lastDisconnect } = update;
        if (connection === "open") {
            loggedOutRetries = 0;
            runtimeStatus.connected = true;
            runtimeStatus.pairingCode = null;
            runtimeStatus.botJid = sock.user?.id || "connected";
            await resolveLockedGroupFromInvite(sock);
            printAuthExportHintOnce();
            console.log("\n==================================================================");
            console.log(`SUCCESS: SHEIKH BOT v8.1 PRO (CLOUD READY) IS ONLINE (${runtimeStatus.botJid})`);
            console.log(`Vault '${CONFIG.vaultName}' Ready: ${vault.items.length} PDFs (${vault.totalSizeMb} MB)`);
            console.log(`Group Lock: ${runtimeStatus.lockedGroupJid || "PENDING"} | DMs: ${CONFIG.allowPrivateDm ? "ON" : "OFF"} | AntiLink: ${liveSettings.antiLink ? "ON" : "OFF"}`);
            console.log("==================================================================\n");
        } else if (connection === "close") {
            runtimeStatus.connected = false;
            const statusCode = lastDisconnect?.error?.output?.statusCode;
            const isLoggedOut = statusCode === DisconnectReason.loggedOut || statusCode === 401;
            if (isLoggedOut && loggedOutRetries < 2) {
                loggedOutRetries += 1;
                fs.rmSync(CONFIG.authDir, { recursive: true, force: true });
                await sleepMs(3000);
                startSheikhBot();
                return;
            }
            if (!isLoggedOut) {
                await sleepMs(4000);
                startSheikhBot();
            }
        }
    });

    // ================= AUTO-WELCOME NEW GROUP MEMBERS =================
    sock.ev.on("group-participants.update", async (ev) => {
        try {
            if (!CONFIG.enableAutoWelcome || ev.action !== "add") return;
            if (runtimeStatus.lockedGroupJid && ev.id !== runtimeStatus.lockedGroupJid) return;
            for (const participant of (ev.participants || [])) {
                const uNum = baseUserId(participant);
                if (!uNum || uNum === baseUserId(sock.user?.id)) continue;
                const welcomeText = AR.msgWelcomeNewMember
                    .replace("{USER}", uNum)
                    .split("{VAULT}").join(CONFIG.vaultName)
                    .split("{COUNT}").join(String(vault.items.length));
                await sendBotMessage(sock, ev.id, { text: welcomeText, mentions: [participant] });
                await sleepMs(1000);
            }
        } catch (err) {
            console.warn("[Welcome Error]:", err.message);
        }
    });

    // ================= MAIN MESSAGE HANDLER =================
    sock.ev.on("messages.upsert", async ({ messages, type }) => {
        if (type !== "notify") return;

        for (const msg of messages) {
            try {
                if (!msg.message) continue;
                if (msg.key && msg.key.id && botSentMessageIds.has(msg.key.id)) continue;

                const remoteJid = msg.key.remoteJid || "";
                if (remoteJid === "status@broadcast") continue;

                const isGroup = remoteJid.endsWith("@g.us");
                if (!isGroup && !CONFIG.allowPrivateDm) continue;
                if (isGroup) {
                    if (!runtimeStatus.lockedGroupJid) await resolveLockedGroupFromInvite(sock);
                    if (runtimeStatus.lockedGroupJid && remoteJid !== runtimeStatus.lockedGroupJid) continue;
                }

                const senderJid = isGroup ? (msg.key.participant || "") : remoteJid;
                const senderName = msg.pushName || "Student";
                const rawText = extractMessageText(msg);
                const hasImage = Boolean(msg.message.imageMessage);

                if (!rawText && !hasImage) continue;

                // Ignore echoed bot templates
                if (rawText && (
                    rawText.startsWith(AR.msgFoundPrefix) ||
                    rawText.startsWith(AR.msgWelcomeHelp.slice(0, 15)) ||
                    rawText.startsWith(AR.msgNotFoundPrefix.slice(0, 15)) ||
                    rawText.startsWith(AR.msgStatsTitle.slice(0, 15))
                )) continue;

                const senderIsAdmin = await isGroupAdmin(sock, remoteJid, senderJid, Boolean(msg.key.fromMe));
                memberStore.touch(senderJid, senderName);
                if (rawText) {
                    memberStore.detectMajor(senderJid, rawText);
                    pushChatHistory(remoteJid, senderName, rawText, isGroup);
                }

                // ================= 1. GROUP PROTECTION GUARDS (NON-ADMINS ONLY) =================
                if (isGroup && !senderIsAdmin && !msg.key.fromMe && senderJid) {
                    if (CONFIG.enableModeration && rawText && moderation.containsProfanity(rawText)) {
                        await applyModerationStrike(sock, remoteJid, msg, senderJid, AR.msgReasonProfanity);
                        continue;
                    }
                    if (liveSettings.antiLink && rawText && moderation.containsUnauthorizedLink(rawText)) {
                        await applyModerationStrike(sock, remoteJid, msg, senderJid, AR.msgReasonLinks);
                        continue;
                    }
                    if (liveSettings.antiSpam && floodGuard.checkFlood(senderJid)) {
                        await sendBotMessage(sock, remoteJid, {
                            text: AR.msgFloodWarn.replace("{USER}", baseUserId(senderJid)),
                            mentions: [senderJid]
                        });
                        continue;
                    }
                }

                // ================= 2. ACTIVE QUIZ / DAILY CHALLENGE ANSWER CHECK =================
                const choiceLetter = rawText ? normalizeChoiceLetter(rawText) : "";
                if (choiceLetter) {
                    // Check Daily Challenge in group
                    if (isGroup && activeDailyChallenge && activeDailyChallenge.groupJid === remoteJid) {
                        if (normalizeChoiceLetter(activeDailyChallenge.answer) === choiceLetter) {
                            const pts = memberStore.addPoints(senderJid, senderName, 10);
                            const winText = `\ud83c\udf89 \u0643\u0641\u0648 \u064a\u0627 @${baseUserId(senderJid)}! \u0625\u062c\u0627\u0628\u0629 \u0635\u062d\u064a\u062d\u0629 (+10 \u0646\u0642\u0627\u0637 | \u0645\u062c\u0645\u0648\u0639\u0643: *${pts}*)\n${activeDailyChallenge.explain}`;
                            activeDailyChallenge = null;
                            await sendBotMessage(sock, remoteJid, { text: winText, mentions: [senderJid] }, { quoted: msg });
                            continue;
                        }
                    }
                    // Check Per-User Active Quiz
                    const qKey = `${remoteJid}::${baseUserId(senderJid)}`;
                    const qState = activeQuizzes.get(qKey);
                    if (qState) {
                        const curQ = qState.questions[qState.idx];
                        const isRight = normalizeChoiceLetter(curQ.answer) === choiceLetter;
                        if (isRight) qState.score += 1;
                        const feedback = isRight
                            ? `\u2705 \u0635\u062d! ${curQ.explain}`
                            : `\u274c \u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629 \u0647\u064a (*${curQ.answer}*). ${curQ.explain}`;
                        qState.idx += 1;
                        if (qState.idx >= qState.questions.length) {
                            activeQuizzes.delete(qKey);
                            const earned = qState.score * 5;
                            const totalPts = memberStore.addPoints(senderJid, senderName, earned);
                            const doneText = `${feedback}\n\n\ud83c\udfc6 *\u0627\u0646\u062a\u0647\u0649 \u0627\u0644\u0643\u0648\u064a\u0632!* \u0646\u062a\u064a\u062c\u062a\u0643: *${qState.score} / ${qState.questions.length}* (+${earned} \u0646\u0642\u0637\u0629 | \u0631\u0635\u064a\u062f\u0643: ${totalPts})`;
                            await sendBotMessage(sock, remoteJid, { text: doneText }, { quoted: msg });
                        } else {
                            const nextText = `${feedback}\n\n${formatQuizQuestion(qState.questions[qState.idx], qState.idx, qState.questions.length, qState.course)}`;
                            await sendBotMessage(sock, remoteJid, { text: nextText }, { quoted: msg });
                        }
                        continue;
                    }
                }

                // ================= 3. GEMINI VISION PHOTO SOLVER =================
                const repliedToBot = isReplyToBot(msg, sock);
                const wakeInCaption = rawText ? AR.wakeWords.some(w => normalizeArabic(rawText).includes(normalizeArabic(w))) : false;
                if (hasImage && CONFIG.geminiApiKey && (!isGroup || wakeInCaption || repliedToBot)) {
                    try {
                        await sock.sendPresenceUpdate("composing", remoteJid);
                        const imgBuffer = await downloadMediaMessage(msg, "buffer", {});
                        if (imgBuffer && imgBuffer.length > 0) {
                            const b64 = imgBuffer.toString("base64");
                            const visionReply = await callGeminiRaw(
                                AR.geminiVisionPrompt,
                                [
                                    { text: rawText || "Explain and solve what is shown in this study photo." },
                                    { inline_data: { mime_type: msg.message.imageMessage.mimetype || "image/jpeg", data: b64 } }
                                ],
                                { temperature: 0.3, maxOutputTokens: 900 }
                            );
                            if (visionReply) {
                                runtimeStatus.visionSolved += 1;
                                await sendBotMessage(sock, remoteJid, { text: visionReply }, { quoted: msg });
                                continue;
                            }
                        }
                    } catch (visErr) {
                        console.warn("[Vision Error]:", visErr.message);
                    }
                }

                if (!rawText) continue;

                // ================= 4. PARSE COMMAND OR PASSIVE FILE ASSIST =================
                const requireWake = isGroup ? (!senderIsAdmin && !repliedToBot) : false;
                let parsed = parseSheikhCommand(rawText, requireWake);

                if (!parsed) {
                    // Passive File Assist in group when student clearly asks for a file without mentioning Sheikh
                    if (isGroup && CONFIG.enablePassiveAssist && hasAnyKeyword(normalizeArabic(rawText), AR.passiveRequestHints)) {
                        const passiveRes = vault.search(rawText);
                        if (passiveRes.matches.length > 0) {
                            await deliverPdfMatches(sock, remoteJid, msg, passiveRes);
                            continue;
                        }
                    }
                    // Optional random friendly banter in group (strictly respects 10-min cooldown & aiChat toggle)
                    if (isGroup && liveSettings.aiChat && CONFIG.geminiApiKey && CONFIG.randomChatChance > 0 && rawText.length >= 8) {
                        if (!userChatCooldown.isUserOnCooldown(senderJid)) {
                            const lastGroupRandom = lastRandomReplyMap.get(remoteJid) || 0;
                            if ((Date.now() - lastGroupRandom) >= (CONFIG.randomChatCooldownSec * 1000) && (Math.random() * 100) < CONFIG.randomChatChance) {
                                lastRandomReplyMap.set(remoteJid, Date.now());
                                userChatCooldown.markUserChatted(senderJid);
                                const banter = await callGeminiAsSheikh(remoteJid, rawText, senderName, senderJid, senderIsAdmin, "RANDOM_BANTER");
                                if (banter && !banter.includes("[[SEND_PDF")) {
                                    await sendBotMessage(sock, remoteJid, { text: banter }, { quoted: msg });
                                    runtimeStatus.aiReplies += 1;
                                }
                            }
                        }
                    }
                    continue;
                }

                console.log(`[Request] ${senderName} (Admin:${senderIsAdmin}) | Type: ${parsed.type} | Text: ${rawText.slice(0, 70)}`);
                runtimeStatus.queriesHandled += 1;

                // ================= 5. ADMIN AUTHORITY COMMANDS =================
                if (parsed.type.startsWith("ADMIN_")) {
                    if (!senderIsAdmin) {
                        await sendBotMessage(sock, remoteJid, { text: AR.msgAdminOnly }, { quoted: msg });
                        continue;
                    }
                    runtimeStatus.adminCommandsExecuted += 1;

                    if (parsed.type === "ADMIN_LOCK" && isGroup) {
                        await sock.groupSettingUpdate(remoteJid, "announcement");
                        await sendBotMessage(sock, remoteJid, { text: AR.msgAdminObeyLock }, { quoted: msg });
                        continue;
                    }
                    if (parsed.type === "ADMIN_UNLOCK" && isGroup) {
                        await sock.groupSettingUpdate(remoteJid, "not_announcement");
                        await sendBotMessage(sock, remoteJid, { text: AR.msgAdminObeyUnlock }, { quoted: msg });
                        continue;
                    }
                    if (parsed.type === "ADMIN_DELETE" && isGroup) {
                        const ctx = msg?.message?.extendedTextMessage?.contextInfo;
                        if (!ctx || !ctx.stanzaId) {
                            await sendBotMessage(sock, remoteJid, { text: AR.msgAdminNeedReply }, { quoted: msg });
                        } else {
                            await sock.sendMessage(remoteJid, {
                                delete: { remoteJid, fromMe: false, id: ctx.stanzaId, participant: ctx.participant }
                            });
                            await sendBotMessage(sock, remoteJid, { text: AR.msgAdminObeyDelete }, { quoted: msg });
                        }
                        continue;
                    }
                    if (parsed.type === "ADMIN_KICK" && isGroup) {
                        const targetJid = getTargetParticipantFromMsg(msg);
                        if (!targetJid) {
                            await sendBotMessage(sock, remoteJid, { text: AR.msgAdminNeedReply }, { quoted: msg });
                        } else if (await isGroupAdmin(sock, remoteJid, targetJid, false)) {
                            await sendBotMessage(sock, remoteJid, { text: AR.msgAdminCannotKickAdmin }, { quoted: msg });
                        } else {
                            await sock.groupParticipantsUpdate(remoteJid, [targetJid], "remove");
                            await sendBotMessage(sock, remoteJid, {
                                text: AR.msgAdminObeyKick.replace("{USER}", baseUserId(targetJid)),
                                mentions: [targetJid]
                            }, { quoted: msg });
                        }
                        continue;
                    }
                    if (parsed.type === "ADMIN_WARN" && isGroup) {
                        const targetJid = getTargetParticipantFromMsg(msg);
                        if (!targetJid) {
                            await sendBotMessage(sock, remoteJid, { text: AR.msgAdminNeedReply }, { quoted: msg });
                        } else {
                            await applyModerationStrike(sock, remoteJid, msg, targetJid, AR.msgReasonAdmin);
                        }
                        continue;
                    }
                    if (parsed.type === "ADMIN_PARDON" && isGroup) {
                        const targetJid = getTargetParticipantFromMsg(msg);
                        if (!targetJid) {
                            await sendBotMessage(sock, remoteJid, { text: AR.msgAdminNeedReply }, { quoted: msg });
                        } else {
                            moderation.resetStrikes(remoteJid, targetJid);
                            await sendBotMessage(sock, remoteJid, {
                                text: AR.msgPardonOk.replace("{USER}", baseUserId(targetJid)),
                                mentions: [targetJid]
                            }, { quoted: msg });
                        }
                        continue;
                    }
                    if (parsed.type === "ADMIN_TAG_ALL" && isGroup) {
                        const meta = await getGroupMetadataSafe(sock, remoteJid);
                        const allJids = (meta?.participants || []).map(p => p.id).filter(Boolean);
                        const body = `\ud83d\udce2 *\u0625\u0639\u0644\u0627\u0646 \u0645\u0646 \u0627\u0644\u0625\u062f\u0627\u0631\u0629:*\n${parsed.message}`;
                        await sendBotMessage(sock, remoteJid, { text: body, mentions: allJids }, { quoted: msg });
                        continue;
                    }
                    if (parsed.type === "ADMIN_LINKS_OFF") {
                        liveSettings.antiLink = false; saveLiveSettings();
                        await sendBotMessage(sock, remoteJid, { text: AR.msgAdminLinksOff }, { quoted: msg });
                        continue;
                    }
                    if (parsed.type === "ADMIN_LINKS_ON") {
                        liveSettings.antiLink = true; saveLiveSettings();
                        await sendBotMessage(sock, remoteJid, { text: AR.msgAdminLinksOn }, { quoted: msg });
                        continue;
                    }
                    if (parsed.type === "ADMIN_CHAT_OFF") {
                        liveSettings.aiChat = false; saveLiveSettings();
                        await sendBotMessage(sock, remoteJid, { text: AR.msgAdminChatOff }, { quoted: msg });
                        continue;
                    }
                    if (parsed.type === "ADMIN_CHAT_ON") {
                        liveSettings.aiChat = true; saveLiveSettings();
                        await sendBotMessage(sock, remoteJid, { text: AR.msgAdminChatOn }, { quoted: msg });
                        continue;
                    }
                    if (parsed.type === "ADMIN_MISSING_LIST") {
                        const list = missingTracker.listTop(15);
                        if (list.length === 0) {
                            await sendBotMessage(sock, remoteJid, { text: AR.msgNoMissing }, { quoted: msg });
                        } else {
                            const text = AR.msgMissingHeader + list.map((m, i) => `${i + 1}. *${m.label}* (${m.count}x)`).join("\n");
                            await sendBotMessage(sock, remoteJid, { text }, { quoted: msg });
                        }
                        continue;
                    }
                }

                // ================= 6. HELP, STATS, LEADERBOARD, CATCH-UP =================
                if (parsed.type === "HELP") {
                    await sendBotMessage(sock, remoteJid, { text: AR.msgWelcomeHelp }, { quoted: msg });
                    continue;
                }
                if (parsed.type === "STATS") {
                    vault.reloadIfNeeded(true);
                    const statsText =
                        `${AR.msgStatsTitle}` +
                        `\u2022 PDF Count: *${vault.items.length}*\n` +
                        `\u2022 Size: *${vault.totalSizeMb} MB*\n` +
                        `\u2022 Anti-Link: *${liveSettings.antiLink ? "ON" : "OFF"}* | AI Chat: *${liveSettings.aiChat ? "ON" : "OFF"}*`;
                    await sendBotMessage(sock, remoteJid, { text: statsText }, { quoted: msg });
                    continue;
                }
                if (parsed.type === "LEADERBOARD") {
                    const top = memberStore.getTop(5);
                    if (top.length === 0) {
                        await sendBotMessage(sock, remoteJid, { text: AR.msgLeaderboardEmpty }, { quoted: msg });
                    } else {
                        const medals = ["\ud83e\udd47", "\ud83e\udd48", "\ud83e\udd49", "4.", "5."];
                        const lines = top.map(([, u], i) => `${medals[i]} *${u.name}* - ${u.points} \u0646\u0642\u0637\u0629`);
                        await sendBotMessage(sock, remoteJid, { text: AR.msgLeaderboardHeader + lines.join("\n") }, { quoted: msg });
                    }
                    continue;
                }
                if (parsed.type === "CATCHUP") {
                    if (!CONFIG.geminiApiKey || groupDailyLog.length === 0) {
                        await sendBotMessage(sock, remoteJid, { text: "\u0644\u0633\u0627 \u0645\u0627 \u0641\u064a \u0631\u0633\u0627\u0626\u0644 \u0643\u0641\u0627\u064a\u0629 \u0627\u0644\u064a\u0648\u0645 \u0639\u0634\u0627\u0646 \u0623\u0644\u062e\u0635\u0644\u0643 \u064a\u0627\u0647\u0627 \ud83d\ude05" }, { quoted: msg });
                        continue;
                    }
                    const transcript = groupDailyLog.slice(-50).map(e => `${e.sender}: ${e.text}`).join("\n");
                    const summary = await callGeminiRaw(AR.geminiCatchupPrompt, [{ text: transcript }], { temperature: 0.4, maxOutputTokens: 500 });
                    if (summary) await sendBotMessage(sock, remoteJid, { text: summary }, { quoted: msg });
                    continue;
                }

                // ================= 7. SUMMARIZE INSIDE PDF =================
                if (parsed.type === "SUMMARIZE") {
                    const courseName = parsed.course || "";
                    const res = vault.search(courseName);
                    if (!CONFIG.geminiApiKey || res.matches.length === 0) {
                        await sendBotMessage(sock, remoteJid, { text: `${AR.msgNotFoundPrefix}${courseName}${AR.msgNotFoundSuffix}` }, { quoted: msg });
                        continue;
                    }
                    await sock.sendPresenceUpdate("composing", remoteJid);
                    const pdfText = await extractPdfTextSnippet(res.matches[0].fullPath, 4500);
                    const promptSys = AR.geminiSummarizePrompt.replace("{COURSE}", res.queryLabel || courseName);
                    const summary = await callGeminiRaw(
                        promptSys,
                        [{ text: pdfText || `File title: ${res.matches[0].storedFilename} | Caption: ${res.matches[0].caption}` }],
                        { temperature: 0.3, maxOutputTokens: 800 }
                    );
                    if (summary) {
                        await sendBotMessage(sock, remoteJid, { text: `\ud83d\udcdd *\u0632\u0628\u062f\u0629 ${res.queryLabel || courseName}:*\n\n${summary}` }, { quoted: msg });
                    }
                    continue;
                }

                // ================= 8. INTERACTIVE QUIZ & DAILY CHALLENGE =================
                if (parsed.type === "QUIZ" || parsed.type === "DAILY_CHALLENGE") {
                    if (!CONFIG.geminiApiKey) continue;
                    const isDaily = parsed.type === "DAILY_CHALLENGE";
                    const targetCourse = isDaily ? "\u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0642\u062f\u0633 \u0623\u0648 \u0627\u0644\u062b\u0642\u0627\u0641\u0629 \u0627\u0644\u0639\u0627\u0645\u0629" : (parsed.course || "\u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0642\u062f\u0633");
                    const numQ = isDaily ? 1 : 5;
                    const res = vault.search(targetCourse);
                    const pdfSnippet = res.matches.length > 0 ? await extractPdfTextSnippet(res.matches[0].fullPath, 3500) : "";
                    const qSys = AR.geminiQuizPrompt.replace("{NUM}", String(numQ)).replace("{COURSE}", targetCourse);
                    const rawJson = await callGeminiRaw(qSys, [{ text: pdfSnippet || `Generate ${numQ} authentic QOU university MCQ(s) for course: ${targetCourse}` }], { temperature: 0.5, maxOutputTokens: 1200, jsonMode: true });
                    try {
                        const questions = JSON.parse(rawJson || "[]");
                        if (Array.isArray(questions) && questions.length > 0) {
                            runtimeStatus.quizzesRun += 1;
                            if (isDaily) {
                                activeDailyChallenge = { ...questions[0], groupJid: remoteJid, createdAt: Date.now() };
                                const dailyMsg = `\u26a1 *\u0633\u0624\u0627\u0644 \u0627\u0644\u064a\u0648\u0645 (+10 \u0646\u0642\u0627\u0637 \u0644\u0623\u0633\u0631\u0639 \u0625\u062c\u0627\u0628\u0629 \u0635\u062d):*\n\n${questions[0].q}\n\n${questions[0].options.join("\n")}`;
                                await sendBotMessage(sock, remoteJid, { text: dailyMsg }, { quoted: msg });
                            } else {
                                const qKey = `${remoteJid}::${baseUserId(senderJid)}`;
                                activeQuizzes.set(qKey, { course: targetCourse, questions, idx: 0, score: 0, userJid: senderJid, userName: senderName });
                                await sendBotMessage(sock, remoteJid, { text: formatQuizQuestion(questions[0], 0, questions.length, targetCourse) }, { quoted: msg });
                            }
                            continue;
                        }
                    } catch (qErr) {
                        console.warn("[Quiz Parse Error]:", qErr.message);
                    }
                }

                // ================= 9. TOP PRIORITY #1: SMART PDF DELIVERY =================
                const isExplicitFileRequest = /(\u0645\u0644\u062e\u0635|\u0633\u0646\u0648\u0627\u062a|\u0627\u0633\u0626\u0644\u0629|\u0623\u0633\u0626\u0644\u0629|\u0627\u0633\u0627\u0644\u0647|\u0623\u0633\u0627\u0644\u0629|\u0643\u062a\u0627\u0628|\u0645\u0644\u0641|pdf|\u0646\u0635\u0641\u064a|\u0646\u0647\u0627\u0626\u064a|\u0627\u0645\u062a\u062d\u0627\u0646|\u062a\u0633\u062a|\u0633\u0644\u0627\u064a\u062f\u0627\u062a|\u0645\u0642\u0631\u0631|\u0645\u0627\u062f\u0629|\u062f\u0648\u0633\u064a\u0629|\u0628\u0646\u0643|\u0646\u0645\u0627\u0630\u062c|\u0646\u0645\u0648\u0630\u062c)/i.test(rawText);
                const directResult = isExplicitFileRequest ? vault.search(parsed.query) : { queryLabel: "", matches: [] };
                if (directResult.matches.length > 0) {
                    await deliverPdfMatches(sock, remoteJid, msg, directResult);
                    continue;
                }

                // ================= 10. PRIORITY #2: AI CHAT (PRIVATE & ADMINS ALWAYS REPLY, NO COOLDOWN) =================
                if (liveSettings.aiChat && CONFIG.geminiApiKey) {
                    const bypassCooldown = !isGroup || senderIsAdmin;
                    if (!bypassCooldown && userChatCooldown.isUserOnCooldown(senderJid)) {
                        runtimeStatus.cooldownSkips += 1;
                        continue;
                    }
                    const aiReply = await callGeminiAsSheikh(remoteJid, rawText, senderName, senderJid, senderIsAdmin, "DIRECT");
                    if (aiReply) {
                        const pdfTagMatch = aiReply.match(/\[\[SEND_PDF:\s*(.+?)\]\]/i);
                        const cleanReply = aiReply.replace(/\[\[SEND_PDF:.*?\]\]/gi, "").trim();
                        if (pdfTagMatch && pdfTagMatch[1]) {
                            const aiResult = vault.search(pdfTagMatch[1].trim());
                            if (aiResult.matches.length > 0) {
                                await deliverPdfMatches(sock, remoteJid, msg, aiResult, cleanReply || null);
                                runtimeStatus.aiReplies += 1;
                                continue;
                            }
                        }
                        if (cleanReply) {
                            if (!bypassCooldown) userChatCooldown.markUserChatted(senderJid);
                            await sendBotMessage(sock, remoteJid, { text: cleanReply }, { quoted: msg });
                            pushChatHistory(remoteJid, "Sheikh", cleanReply, isGroup);
                            runtimeStatus.aiReplies += 1;
                            continue;
                        }
                    }
                }

                // ================= 11. MISSING COURSE LOG + POLITE NOT-FOUND =================
                if (directResult.queryLabel && (senderIsAdmin || !userChatCooldown.isUserOnCooldown(senderJid))) {
                    missingTracker.record(directResult.queryLabel, senderName);
                    await sendBotMessage(
                        sock,
                        remoteJid,
                        { text: `${AR.msgNotFoundPrefix}${directResult.queryLabel}${AR.msgNotFoundSuffix}` },
                        { quoted: msg }
                    );
                }
            } catch (err) {
                console.error("[Message Handler Error]:", err.message);
            }
        }
    });
}

if (require.main === module) {
    setInterval(() => {
        console.log(`[Heartbeat] Online:${runtimeStatus.connected} | Vault:${vault.items.length} | Sent:${runtimeStatus.filesSent} | Quizzes:${runtimeStatus.quizzesRun} | Vision:${runtimeStatus.visionSolved} | AdminCmds:${runtimeStatus.adminCommandsExecuted}`);
    }, 300000);

    const server = http.createServer((req, res) => {
        if (req.url === "/health") {
            res.writeHead(200, { "Content-Type": "application/json" });
            res.end(JSON.stringify({ status: "ok", version: "8.0-pro", uptime: process.uptime() }));
            return;
        }
        res.writeHead(200, { "Content-Type": "application/json; charset=utf-8" });
        res.end(JSON.stringify({
            bot: CONFIG.botName,
            vaultName: CONFIG.vaultName,
            ...runtimeStatus,
            indexedUniquePdfs: vault.items.length,
            vaultSizeMb: vault.totalSizeMb,
            liveSettings
        }, null, 2));
    });
    server.listen(CONFIG.httpPort, "0.0.0.0", () => {
        console.log(`[HTTP Keep-Alive] Listening on port ${CONFIG.httpPort} (/health and /status)`);
    });

    startSheikhBot().catch((err) => {
        console.error("[Fatal Startup Error]:", err);
        process.exit(1);
    });
}

module.exports = {
    CONFIG, AR, normalizeArabic, stripAlPrefix, isOneEditAway, parseCsvLine,
    SheikhVaultIndex, ModerationManager, MemberStore, MissingTracker,
    parseSheikhCommand, normalizeChoiceLetter, FloodGuard
};
